#!/usr/bin/env python3
"""Independent expected results for the EMAX validation scenarios (issue #545).

This shares no code with the Go engine and never runs it. It implements the
rules written in ../../emax-validation.org, in exact arithmetic: prices are
integer points (1/100000), money is integer cents, EMAs are Fractions.

    python3 emax_expected.py bars    overwrite the scenario CSVs from BARS below
    python3 emax_expected.py tables  read the CSVs, recompute, rewrite the tables

Overwriting the CSVs is fine; review the diff. Never change an expected value
to make a failing Go test pass without finding out which side is wrong.
"""
import sys
from datetime import date, timedelta
from fractions import Fraction
from pathlib import Path

HERE = Path(__file__).resolve().parent
DOC = HERE.parent.parent / "emax-validation.org"
MARKER = "# Everything below is generated by testdata/emax/emax_expected.py tables. Do not edit by hand.\n"

SHORT, LONG = 2, 4
START_CENTS = 1_000_000  # $10,000.00
FIRST_DAY = date(2010, 1, 4)  # a Monday
MIN_EMA_GAP = 5  # points: every warm bar's EMAs must differ by at least this


def row(o, h, l, c):
    return (o, h, l, c)


# Warm-up shared by the long scenarios: the first signal is long on bar 3.
