# ---------------------------------------------------------------- arithmetic


def floor_div(a, b):
    return a // b  # Python floors toward negative infinity


def ceil_div(a, b):
    return -((-a) // b)


def fmt_price(p):
    return f"{p // 100000}.{p % 100000:05d}"


def fmt_money(c):
    sign = "-" if c < 0 else ""
    c = abs(c)
    return f"{sign}${c // 100:,}.{c % 100:02d}"


def fmt_cents_exact(f):
    """An exact cent amount to three places; every P/L here is a whole number of mills."""
    mills = f * 1000
    assert mills.denominator == 1, f
    n = abs(mills.numerator)
    return f"{'-' if f < 0 else ''}{n // 1000}.{n % 1000:03d}"


def fmt_planned(cents):
    """Planned risk in exact dollars, never rounded: units * distance is in 1/100000 of a dollar."""
    units = cents * 1000
    assert units.denominator == 1, cents
    n = units.numerator
    return f"${n // 100000:,}.{n % 100000:05d}"


def fmt_ema(f):
    return f"{float(f) / 100000:.7f}"


def bar_date(i):
    """The i-th weekday from FIRST_DAY."""
    d = FIRST_DAY
    for _ in range(i):
        d += timedelta(days=1)
        while d.weekday() >= 5:
            d += timedelta(days=1)
    return d


# ---------------------------------------------------------------- CSV


def csv_path(name):
    d = bar_date(0)
    return (HERE / name / "data" / "synthetic" / "canonical" / "EURUSD" / f"{d.year}" / f"{d.month:02d}"
            / f"EURUSD-{d.year}-{d.month:02d}-D1.csv")


def write_bars(name, scen):
    path = csv_path(name)
    path.parent.mkdir(parents=True, exist_ok=True)
    d0 = bar_date(0)
    lines = [
        f"# schema=design-bars-v1 source=synthetic instrument=EURUSD tf=d1 year={d0.year} month={d0.month:02d} scenario={name}",
        "time,open,high,low,close,volume",
    ]
    for i, (o, h, l, c) in enumerate(scen["bars"]):
        lines.append(f"{bar_date(i).isoformat()}T00:00:00Z,{fmt_price(o)},{fmt_price(h)},{fmt_price(l)},{fmt_price(c)},1000")
    path.write_text("\n".join(lines) + "\n")


def read_points(s):
    whole, frac = s.split(".")
    assert len(frac) == 5, s
    return int(whole) * 100000 + int(frac)


def read_bars(name):
    rows = []
    for line in csv_path(name).read_text().splitlines()[2:]:
        t, o, h, l, c, _ = line.split(",")
        rows.append((t, read_points(o), read_points(h), read_points(l), read_points(c)))
    return rows


def check_bars(name, bars):
    """The fixture rules: wrong-field and wrong-bar mistakes must change a result."""
    prev_close = None
    for i, (t, o, h, l, c) in enumerate(bars):
        want = f"{bar_date(i).isoformat()}T00:00:00Z"
        assert t == want, f"{name} bar {i}: timestamp {t}, want {want}"
        assert h > max(o, c) and l < min(o, c), f"{name} bar {i}: high and low must straddle open and close"
        if prev_close is not None:
            assert o != prev_close, f"{name} bar {i}: open must differ from the previous close"
        prev_close = c


# ---------------------------------------------------------------- simulation


class Order:
    def __init__(self, kind, side, made, ref, why):
        self.id = ""
        self.kind, self.side, self.made, self.ref, self.why = kind, side, made, ref, why
        self.units, self.stop = 0, 0
        self.state, self.fill, self.ended = "submitted", None, None
        self.note = ""


def run(name, bars):
    balance = START_CENTS
    pos = None  # dict side, units, entry, mark, entry_bar
    waiting, completed, trades, events = [], [], [], []
    phase = "Open"
    seq = 0
    ema_s, ema_l = None, None
    closes = []
    want, pending = "none", "none"  # EMAX's signal state, not the position
    ema_rows = []

    def event(i, order_id, text):
        events.append((i, phase, order_id, text))

    def next_id():
        nonlocal seq
        seq += 1
        return f"sim-{seq}"

    def pnl_exact(side, units, entry, exit_):
        d = exit_ - entry if side == "long" else entry - exit_
        return Fraction(d * units * 100, 100000)

    def margin(units, p):  # units * price * 2%, in cents, rounded up
        return ceil_div(units * p * 2 * 100, 100 * 100000)

    def unrealized():
        if pos is None:
            return 0
        exact = pnl_exact(pos["side"], pos["units"], pos["entry"], pos["mark"])
        return floor_div(exact.numerator, exact.denominator)

    def finish(o, i, state, fill=None, why=""):
        o.state, o.fill, o.ended, o.note = state, fill, i, why
        waiting.remove(o)
        completed.append(o)

    def fill_close(o, i, p):
        nonlocal balance, pos
        exact = pnl_exact(pos["side"], pos["units"], pos["entry"], p)
        cents = floor_div(exact.numerator, exact.denominator)
        balance += cents
        o.units = pos["units"]
        trades.append({
            "side": pos["side"], "units": pos["units"], "entry_bar": pos["entry_bar"], "entry": pos["entry"],
            "exit_bar": i, "exit": p, "why": o.why, "exact": exact, "cents": cents,
            "planned": pos["planned"],
        })
        if o.why == "strategy":
            event(i, o.id, f"Strategy close fills at {fmt_price(p)}; P/L {fmt_money(cents)}")
        elif p == o.ref:
            event(i, o.id, f"{o.side.capitalize()} stop fills at {fmt_price(p)}; P/L {fmt_money(cents)}")
        else:
            event(i, o.id, f"{o.side.capitalize()} stop fills at the open, {fmt_price(p)}, past its "
                           f"{fmt_price(o.ref)} level; P/L {fmt_money(cents)}")
        pos = None
        finish(o, i, "filled", p)
        for x in list(waiting):  # the position's other exits go with it
            if x.kind == "close" and x.why != "strategy":
                finish(x, i, "cancelled", why="position closed")
                event(i, x.id, f"{x.side.capitalize()} stop cancelled: position closed")

    for i, (t, o_, h, l, c) in enumerate(bars):
        # 1. The broker: first what the open alone triggers, then the whole range.
        for phase, hi, lo in (("Open", o_, o_), ("Range", h, l)):
            for o in [x for x in waiting if x.why == "strategy" and x.made < i]:
                if o.kind == "close" and pos is None:
                    finish(o, i, "rejected", why="no position to close")
                    event(i, o.id, "Close rejected: no position to close")
                elif o.kind == "close":
                    fill_close(o, i, o_)
                else:
                    need, avail = margin(o.units, o_), balance + unrealized()
                    assert need <= avail, f"{name} bar {i}: margin at the fill"
                    assert pos is None
                    pos = {"side": o.side, "units": o.units, "entry": o_, "mark": o_, "entry_bar": i,
                           "planned": o.planned}
                    finish(o, i, "filled", o_)
                    event(i, o.id, f"{o.side.capitalize()} fills at {fmt_price(o_)}: {o.units} units")
                    x = Order("close", o.side, i, o.stop, "stop loss")
                    x.id = next_id()
                    waiting.append(x)
                    event(i, x.id, f"{o.side.capitalize()} stop placed at {fmt_price(o.stop)}")
            for o in [x for x in waiting if x.why == "stop loss"]:
                if o.side == "long" and lo <= o.ref:
                    fill_close(o, i, min(o.ref, o_))
                elif o.side == "short" and hi >= o.ref:
                    fill_close(o, i, max(o.ref, o_))

        # A stop missed by one point is the fixture's sharpest check: say so.
        for o in [x for x in waiting if x.why == "stop loss"]:
            if o.side == "long" and l - o.ref == 1:
                event(i, o.id, f"Low {fmt_price(l)}; stop {fmt_price(o.ref)}; no fill")
            elif o.side == "short" and o.ref - h == 1:
                event(i, o.id, f"High {fmt_price(h)}; stop {fmt_price(o.ref)}; no fill")

        # 2. Value the position at the close; the margin rules must not fire here.
        if pos is not None:
            pos["mark"] = c
            assert balance + unrealized() >= margin(pos["units"], c), f"{name} bar {i}: margin warning"

        # 3. EMAX sees the bar's close.
        phase = "Strategy"
        closes.append(c)
        n = len(closes)
        order = None
        why = ""
        if n == SHORT:
            ema_s = Fraction(sum(closes[:SHORT]), SHORT)
        elif n > SHORT:
            ema_s += Fraction(2, SHORT + 1) * (c - ema_s)
        if n == LONG:
            ema_l = Fraction(sum(closes[:LONG]), LONG)
        elif n > LONG:
            ema_l += Fraction(2, LONG + 1) * (c - ema_l)
        s, l_ = ema_s, ema_l

        def make_open(side):
            dist = max(c // 100, 1)  # 1% of the close, rounded down, at least a point
            stop = c - dist if side == "long" else c + dist
            eq = balance + unrealized()
            reserved = sum(margin(x.units, x.ref) for x in waiting if x.kind == "open")
            used = margin(pos["units"], pos["mark"]) if pos else 0
            risk_units = eq * 10000 * 100000 // (1000000 * dist * 100)
            margin_units = (eq - used - reserved) * 100000 * 1000000 // (c * 20000 * 100)
            o = Order("open", side, i, c, "strategy")
            o.units, o.stop = min(risk_units, margin_units), stop
            assert risk_units <= margin_units, f"{name} bar {i}: this table assumes the risk limit binds"
            o.planned = Fraction(o.units * dist * 100, 100000)
            return o

        if n >= LONG:
            assert abs(s - l_) >= MIN_EMA_GAP, f"{name} bar {i}: EMAs too close to call: {float(s - l_)}"
            trend = "long" if s > l_ else "short"
            if pending != "none":
                d, pending = pending, "none"
                want = d
                order = make_open(d)
                why = "Pending side, trend not re-checked: "
            elif trend != want:
                if want == "none":
                    want = trend
                    order = make_open(trend)
                    why = f"EMAs warm, EMA(2) {'above' if s > l_ else 'below'} EMA(4): "
                else:
                    want, pending = "none", trend
                    order = Order("close", "none", i, c, "strategy")
                    why = f"EMA(2) {'above' if s > l_ else 'below'} EMA(4): "
        if order is not None:
            order.id = next_id()
            waiting.append(order)
            if order.kind == "open":
                event(i, order.id, f"{why}{order.side} submitted, {order.units} units, stop {fmt_price(order.stop)}")
            else:
                event(i, order.id, f"{why}close submitted")
        elif n >= LONG and pos is None and want != "none":
            event(i, "", f"Flat; EMAX signal state still {want}; no order")
        ema_rows.append((s, l_))

    return {
        "balance": balance, "pos": pos, "waiting": waiting, "completed": completed, "trades": trades,
        "events": events, "emas": ema_rows, "want": want, "pending": pending, "unrealized": unrealized(),
        "used": margin(pos["units"], pos["mark"]) if pos else 0,
        "reserved": sum(margin(x.units, x.ref) for x in waiting if x.kind == "open"),
    }


# ---------------------------------------------------------------- tables


def table(rows):
    return "".join("| " + " | ".join(str(c) for c in r) + " |\n" if r != "-" else "|-\n" for r in rows)


def order_request(o):
    if o.kind == "open":
        return f"Open {o.side}, market"
    return "Close position, market" if o.why == "strategy" else f"Stop loss on {o.side}, stop"


def order_price(o):
    if o.why == "stop loss":
        return f"trigger {fmt_price(o.ref)}"
    text = f"signal close {fmt_price(o.ref)}"
    return f"{text}; stop {fmt_price(o.stop)}" if o.kind == "open" else text


def render(name, scen, bars, res):
    out = [f"\n** {name}: {scen['title']}\n", f"{scen['shows']}\n\n"]
    out.append(f"Bars: =testdata/emax/{name}/data/synthetic/canonical/EURUSD/2010/01/EURUSD-2010-01-D1.csv=\n\n")

    rows = [["bar", "date", "open", "high", "low", "close", "EMA(2)", "EMA(4)", "EMA(2) - EMA(4), points"], "-"]
    for i, (t, o, h, l, c) in enumerate(bars):
        s, l_ = res["emas"][i]
        rows.append([i, t[:10], fmt_price(o), fmt_price(h), fmt_price(l), fmt_price(c),
                     fmt_ema(s) if s is not None else "not warm", fmt_ema(l_) if l_ is not None else "not warm",
                     f"{float(s - l_):+.2f}" if s is not None and l_ is not None else ""])
    out.append(table(rows) + "\n")

    rows = [["bar", "phase", "order", "event"], "-"]
    rows += [[i, phase, order_id, text] for i, phase, order_id, text in res["events"]]
    out.append("Event timeline:\n\n" + table(rows) + "\n")

    if res["trades"]:
        rows = [["side", "units", "entry bar", "entry", "exit bar", "exit", "exit why", "P/L before rounding (cents)", "P/L", "planned risk"], "-"]
        for t in res["trades"]:
            rows.append([t["side"], t["units"], t["entry_bar"], fmt_price(t["entry"]), t["exit_bar"], fmt_price(t["exit"]),
                         t["why"], fmt_cents_exact(t["exact"]), fmt_money(t["cents"]), fmt_planned(t["planned"])])
        out.append("Closed trades:\n\n" + table(rows) + "\n")
    else:
        out.append("Closed trades: none.\n\n")

    equity = res["balance"] + res["unrealized"]
    realized = sum(t["cents"] for t in res["trades"])
    assert START_CENTS + realized == res["balance"]
    p = res["pos"]
    rows = [["final state", "value"], "-",
            ["start balance", fmt_money(START_CENTS)],
            ["realized P/L (sum of trades)", fmt_money(realized)],
            ["balance", fmt_money(res["balance"])],
            ["position", f"{p['side']} {p['units']} from {fmt_price(p['entry'])}, marked {fmt_price(p['mark'])}" if p else "none"],
            ["unrealized P/L", fmt_money(res["unrealized"])],
            ["equity", fmt_money(equity)],
            ["used margin", fmt_money(res["used"])],
            ["reserved margin", fmt_money(res["reserved"])],
            ["EMAX signal state", res["want"]],
            ["EMAX pending side", res["pending"]]]
    out.append(table(rows) + "\n")

    rows = [["order", "request", "made on bar", "price when made", "units filled", "ended on bar", "outcome", "fill price"], "-"]
    for o in res["completed"]:
        outcome = o.state if o.state == "filled" else f"{o.state}: {o.note}"
        rows.append([o.id, order_request(o), o.made, order_price(o), o.units if o.state == "filled" else "not filled",
                     o.ended, outcome, fmt_price(o.fill) if o.state == "filled" else "not filled"])
    out.append("Completed orders, in the order they ended:\n\n" + table(rows) + "\n")

    if res["waiting"]:
        rows = [["order", "request", "made on bar", "price when made", "units"], "-"]
        for o in res["waiting"]:
            rows.append([o.id, order_request(o), o.made, order_price(o), o.units if o.kind == "open" else "whole position"])
        out.append("Orders still waiting at the end of the data:\n\n" + table(rows))
    else:
        out.append("Orders still waiting at the end of the data: none.\n")
    return "".join(out)


def render_exact(name, res):
    rows = [["bar", "EMA(2)", "EMA(4)"], "-"]
    for i, (s, l_) in enumerate(res["emas"]):
        if s is not None:
            rows.append([i, s, l_ if l_ is not None else "not warm"])
    return f"\n** {name}\n" + table(rows)


def main():
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    if cmd == "bars":
        for name, scen in SCENARIOS.items():
            write_bars(name, scen)
    elif cmd == "tables":
        parts, exact = [], []
        for name, scen in SCENARIOS.items():
            bars = read_bars(name)
            check_bars(name, bars)
            res = run(name, bars)
            parts.append(render(name, scen, bars, res))
            exact.append(render_exact(name, res))
        text = DOC.read_text()
        exact_head = "\n* Exact EMAs\nThe rounded EMAs above are for reading. These are the exact values, in points.\n"
        DOC.write_text(text[: text.index(MARKER) + len(MARKER)] + "".join(parts) + exact_head + "".join(exact))
    else:
        sys.exit(__doc__)


if __name__ == "__main__":
    main()
